using Pre2Port.Native;

namespace Pre2Port.Game.Frontend;

/// <summary>
/// Port-only (FULLSCREEN=WIDESCREEN, presentation only): side margins of the ATTRACT title ("Prehistorik 2" over the jungle, MENU2.SQZ), generated by RULES.
/// No image data is stored and no reference PNG is used. Two methods, chosen per band of rows from measurements on the game's own 320x200 base:
/// <list type="bullet">
/// <item><b>Pattern</b> (rows 168..199, grass strip + rock wall): the strip repeats with period 64 (99.7 % of the pixels of rows 168..199 equal the ones 64 px to the
/// right; 320 = 5 x 64, so the tile is aligned at both edges). The margin continues that tile exactly: the pixel at distance d to the left of the frame is base column
/// (-1 - d) mod 64, to the right it is column d mod 64.</item>
/// <item><b>Bands</b> (rows 0..167: sky, horizon, jungle): no period (best 0.52 for the sky, 0.49 for the jungle), so the same rule as <see cref="WideArt"/> /
/// <see cref="WideMenuArt"/>: per band of rows the margin pixel at distance d copies base pixel s of that row's edge strip (width W, walked back and forth so the seam is
/// continuous); each tile of W pixels moves its source row by dy(k) (amplitude Step, reflected at the band limits) so the foliage does not repeat identically.</item>
/// </list>
/// The source of the margins is the TEXT/SPRITE-FREE base (<c>MenuAssets.AttractImage</c>), never the composed frame: the caveman starts at X = 0 and the monsters leave through the
/// edges, so copying the frame would smear them into the margin. The centred 320 frame (with its sprites) is drawn as is; the sprites that cross its edge are continued through the margins (see <c>sprites</c> in <see cref="Attract"/>).
/// Every margin pixel is an index of the base, so the title palette and its fades apply unchanged.
/// </summary>
public static class WideAttractArt
{
    /// <summary>One band of rows [Y0, Y1): strip width W, row-shift amplitude Step (0 = none); Period &gt; 0 = repeat the base with that period instead of mirroring.</summary>
    readonly record struct Band(int Y0, int Y1, int W, int Step, int Period = 0);

    // Left: sky (0..113: the whole edge column is one index, so W = 1 = the row's edge pixel; the distant palm top at x = 5..12 must not be mirrored), horizon hills (114..123; W 9 stops before the thin trunk at x = 9) (124..167), grass + rock wall (168..199, period 64).
    static readonly Band[] Left = { new(0, 114, 1, 0), new(114, 124, 9, 2), new(124, 168, 24, 5), new(168, 200, 0, 0, 64) };
    // Right: sky (0..105, one index as well), the rock mound at the edge (106..123), jungle (124..167), grass + rock wall (168..199, period 64).
    static readonly Band[] Right = { new(0, 106, 1, 0), new(106, 124, 12, 3), new(124, 168, 24, 5), new(168, 200, 0, 0, 64) };

    /// <summary>
    /// Copies the 320 frame <paramref name="src"/> centred into <paramref name="dst"/> (palette included) and fills both margins from the sprite-free
    /// 320x200 <paramref name="bg"/> by the band rules. <paramref name="sprites"/> (optional; <see cref="AttractScene.SpriteLayer"/>) returns the sprite layer of the screen shifted by dx
    /// (0xFF = none): the sprites cross the 320 frame edge into the margin, in chunks of at most 320 columns, instead of being cut at an invisible line (the caveman leaves to the
    /// right, the monsters come back from the right and the caveman ends at the left edge), like the tally sprites in <see cref="WideEnd"/>.
    /// </summary>
    public static void Attract(Framebuffer src, byte[] bg, Framebuffer dst, Func<int, byte[]?>? sprites = null)
    {
        int w = dst.Width, sw = src.Width, m = (w - sw) / 2, mr = w - m - sw;
        Array.Copy(src.Palette, dst.Palette, dst.Palette.Length);
        for (int y = 0; y < dst.Height; y++) Array.Copy(src.Pixels, y * sw, dst.Pixels, y * w + m, sw);
        Fill(bg, sw, dst, Left, m, left: true);
        Fill(bg, sw, dst, Right, mr, left: false);
        if (sprites is null) return;
        for (int side = 0; side < 2; side++)
        {
            int from = side == 0 ? 0 : m + sw, to = side == 0 ? m : w;
            for (int c0 = from; c0 < to; c0 += sw)
            {
                var layer = sprites(m - c0);                      // pass column j shows world x = (c0 + j) - m
                if (layer is null) continue;
                int n = Math.Min(sw, to - c0);
                for (int y = 0; y < dst.Height; y++)
                    for (int j = 0; j < n; j++)
                    {
                        byte v = layer[y * sw + j];
                        if (v != 0xFF) dst.Pixels[y * w + c0 + j] = v;
                    }
            }
        }
    }

    static void Fill(byte[] bg, int sw, Framebuffer dst, Band[] bands, int margin, bool left)
    {
        int w = dst.Width, m = (w - sw) / 2;
        foreach (var b in bands)
            for (int y = b.Y0; y < b.Y1 && y < dst.Height; y++)
                for (int d = 0; d < margin; d++)
                {
                    byte v;
                    if (b.Period > 0)
                        v = bg[y * sw + (left ? ((-1 - d) % b.Period + b.Period) % b.Period : (sw + d) % b.Period)];
                    else
                    {
                        int k = d / b.W, t = d % (2 * b.W), s = t < b.W ? t : 2 * b.W - 1 - t;
                        int dy = b.Step == 0 ? 0 : k * b.Step % (2 * b.Step + 1) - b.Step;
                        int sy = y + dy; if (sy < b.Y0) sy = 2 * b.Y0 - sy; else if (sy >= b.Y1) sy = 2 * (b.Y1 - 1) - sy;   // reflected at the band limits (a clamp would repeat the first row as a flat bar)
                        v = bg[sy * sw + (left ? s : sw - 1 - s)];
                    }
                    dst.Pixels[y * w + (left ? m - 1 - d : m + sw + d)] = v;
                }
    }
}
